dir$s642.prototype = new DirEvent();
dir$s642.prototype.beforeInit = function(renderType){
  this._dir.options._files = null;
  document._dir = this._dir;
}
dir$s642.prototype.afterInit = function(renderType){
  var p = this._dir, g = p.grid(0),g2 = p.grid(1);
  var exp = {
	tien: ['*tien', '[tien]*1'],
	t_tien: ['@t_tien','[tien]'],
  }
  p.applyExpression(exp, g, false);




  g.FomulaApplied = {
	"ty_gia":["t_tien"],
	"tien":["t_tien"],
	"ma_pttt":["t_tien"],
  }
  //console.log(JSON.stringify(g.FomulaApplied)); //Gan la ds cong thuc tinh cho cot nao do: 

 // p.options.FCColumns = {FC: ['t_tien_nt2', 't_thue_nt', 't_tt_nt', 't_tc_tien_nt2'], BC: ['t_tien2', 't_thue', 't_tt', 't_tc_tien2']};
  //g.FCColumns = {FC: ['gia_nt2', 'tien_nt2'], BC: ['gia2', 'tien2']};

  p.options.FCColumns = {FC: [], BC: []};
  g.FCColumns = {FC: [], BC: []};

  var oldTG = '', oTG = p.jObject('ma_nt'); //Neu ty gia thay doi
  oTG.focus(function(){ oldTG = oTG.fval(); }).blur(function(){ if (oldTG != oTG.fval()) onExRateChanged(oTG, p);});
  p.applyFCColumns();
  p.applyFCColumns(g);
 // p.setFCHidden(oTG.fval());

  dir$s642DisabledMasterField(p, g);
  dir$s642HiddenColumnByType(p);
  dir$s642HiddenColumnByTran(p);
  dir$s642DisabledMasterPort(p);
  dir$s642DisabledStatusByAction(p);
  dir$s642LoadDataQuote(p);
  p.find(".control-label.t_so_luong, .control-label.t_tien_nt2, .control-label.t_thue_nt, .control-label.t_tt_nt, .input-field.t_so_luong, .input-field.t_tien_nt2, .input-field.t_tien2, .input-field.t_thue_nt, .input-field.t_thue, .input-field.t_tt_nt, .input-field.t_tt").css("font-weight", "bold");
}

dir$s642.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir, g = p.grid(0), dt = g.data;
  switch (id) {
    case 'ok':
		var hoanung = p.valForm('t_tien'),tamung = p.valForm('t_tien_tu');
		if (p.valForm('t_tien') > p.valForm('t_tien_tu')) { 

			$.alert(p.msg('failsave')+' ' + hoanung + ' > ' + tamung);			
			return false;
			Break;
			}

    default:
      break;
  }
  return true;
}
dir$s642.prototype.beforeButtonGridClick = function (id, gindex) {

  var p = this._dir;
  switch (id) {
	case '10':
     if (p.valForm('ma_noi_di').trim() == '') {
        p.jObject('ma_noi_di').focus(); 
        return;
      }if (p.valForm('ma_noi_den').trim() == '') {
        p.jObject('ma_noi_den').focus(); 
        return;
      }if (p.valForm('id_bg') == 0) {
		$.showToast(p.msg('HaveIDBG'));
        return;
      }
       p.showFilter("s642BQ1", null, {_ngay_ct: p.valForm('ngay_ct'),_ngay_ct1: p.valForm('ngay_hl'),_ngay_ct2: p.valForm('ngay_hld'),_ma_noi_di: p.valForm('ma_noi_di'), _ten_noi_di: p.valForm('ten_noi_di'), _ma_noi_den: p.valForm('ma_noi_den'), _ten_noi_den: p.valForm('ten_noi_den'), _id_bg: p.valForm('id_bg')});	  
	  p.setInactive([ 'ma_noi_di','ma_noi_den'], false);
	  return false;
      break;
    case '20':
        var p = document._dir;
		if (p.valForm('id_bg') != '') {
			$.showToast(p.msg('NewOrder'));
			return;
		 }
	   if (p.valForm('ma_noi_di').trim() == '') {
        p.jObject('ma_noi_di').focus(); 
        return;
      }if (p.valForm('ma_noi_den').trim() == '') {
        p.jObject('ma_noi_den').focus(); 
        return;
      }
	  if (p.valForm('ds_cong').trim() == '') {
		$.showToast(p.msg('EmptyContainer'));
        p.jObject('ds_cong').focus(); 
        return;
      }  
      p.showFilter("s642BN1", null, {_ngay_ct: p.valForm('ngay_ct'),_ngay_ct1: p.valForm('ngay_hl'),_ngay_ct2: p.valForm('ngay_hld'),_unit_id: p.valForm('unit_id'),_id_dh: p.valForm('id_dh'),_ma_noi_di: p.valForm('ma_noi_di'),_ds_cong: p.valForm('ds_cong'), _ten_noi_di: p.valForm('ten_noi_di'), _ma_noi_den: p.valForm('ma_noi_den'), _ten_noi_den: p.valForm('ten_noi_den'),_ma_hang: p.valForm('ma_hang'), _ten_hang: p.valForm('ten_hang')});
	 return false;
      break;
    default:
      break;
  }
  return true;
}
