function dir$s642LoadDataQuote(p){
var pa = p.options.parent;
	p.setDisabled(['ma_job','so_job','ma_nv','ngay_hl','ngay_hld','ma_gd','ma_pttt','dien_giai','t_tien_tu','so_ct','ma_nt','ty_gia','ngay_ct'], true);
